vec2 hash2(vec2 seed) { //as far as I can tell,to make a hash you basically just add a bunch of numbers
    vec2 hash = fract(seed.yx * vec2(1.1042, 1.10523)); // to try and make everything as jumbled as possible
    hash += dot(hash, hash.yx - 222.6234); // Then you fract() it to get it in the 0 - 1 range
    hash *= fract(hash + .99340184015);
    hash -= dot(fract(hash), hash);
    hash = fract(hash.yx - hash.xx * 12.);
    hash *= 1.; // this makes the results smaller, so the two spheres don't get too far apart
    return hash;
}

float Smooth(float p1, float p2, float strength) {
    float temp = clamp(.5 + .5 * (p2 - p1) / strength, 0., 1.);
    return mix(p2, p1, temp) - strength * temp * (1. - temp);
}

vec3 calcNormal(vec2 point, vec2 uv) {
    vec3 normal;

    //for a single point:
    //normal.xy = point - uv;

    //specialized use-case:
    vec2 point1 = (point - hash2(point - floor(iTime * .3))) - uv; //get the two points
    vec2 point2 = (point + hash2(point + floor(iTime * .5))) - uv;
    vec2 point3 = (point + hash2(point - floor(iTime * .6))) - uv;
    vec2 point4 = (point - hash2(point + floor(iTime * .1))) - uv;

    float normal1 = Smooth(abs(length(point1)), abs(length(point2)), .5);// * point - uv; //use the min() function to combine the absolute sdfs, then apply the signs again
    float normal2 = Smooth(abs(length(point3)), abs(length(point4)), .5);// * point - uv;

    normal.xy = Smooth(normal1, normal2, .5) * (point - uv);

    // calculate an arc using cosine(arcsine(xy)), I'm not sure why ¯\_(ツ)_/¯
    normal.z = cos(asin(length(normal.xy))); 
    if (length(normal.xy) > 1.) {
        normal = vec3(0., 0., 0.); //ignore points that aren't in the sphere's radius
    }
    return normal;
}

#define thickness .5

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = (2. * fragCoord - iResolution.xy) / iResolution.x;
    uv *= 4.;

    vec3 col = calcNormal(vec2(0.2,  0.1), uv);

    uv = fragCoord / iResolution.xy;

    //uv /= sign(col.xy) * col.z; //makes it look kind of raytraced when viewing the UV.

    uv -= refract(vec3(0, 0, -1), col, 1./1.3).xy * thickness; //1. / 1.3 is the index for air to water.

    vec4 view = texture(iChannel0, uv);

    view += clamp(dot(col, vec3(.2, .4, .3)), 0., .4);

    // Output to screen
    fragColor = view;
    //fragColor = vec4(col, 1.);
    //fragColor = vec4(uv, 0., 1.);
}
